def split_existing_money(apps, schema_editor):
    """Older refunds count as the farm's part; older paid card sales count as paid straight to the farm."""
    from decimal import Decimal
    Refund = apps.get_model("orders", "Refund")
    SubOrder = apps.get_model("orders", "SubOrder")
    SiteSettings = apps.get_model("core", "SiteSettings")
    rate = getattr(SiteSettings.objects.first(), "commission_rate", None) or Decimal("0.05")
    for r in Refund.objects.all():
        Refund.objects.filter(pk=r.pk).update(farm_amount=r.amount, commission_amount=0, delivery_amount=0,
                                              status="processed")
    for sub in SubOrder.objects.filter(order__payment_method="card", order__payment__status__in=[
            "paid", "refunded", "part_refund"], paid_to_farm=False):
        commission = (sub.goods_subtotal * rate).quantize(Decimal("0.01"))
        SubOrder.objects.filter(pk=sub.pk).update(paid_to_farm=True,
                                                  farm_share=sub.goods_subtotal + sub.vat_amount - commission)



